// QRCode.js - Минимальная версия для генерации QR-кодов
(function(global) {
    function QRCode(options) {
        if (!(this instanceof QRCode)) return new QRCode(options);
        this._element = options.element;
        this._value = options.value || '';
        this._size = options.size || 200;
        this._bgColor = options.bgColor || '#ffffff';
        this._fgColor = options.fgColor || '#000000';
        this._generate();
    }

    QRCode.prototype._generate = function() {
        if (!this._element) return;
        const canvas = this._element;
        const ctx = canvas.getContext('2d');
        const size = this._size;
        const data = this._value;
        
        canvas.width = size;
        canvas.height = size;
        ctx.fillStyle = this._bgColor;
        ctx.fillRect(0, 0, size, size);
        
        if (!data) {
            ctx.fillStyle = '#999';
            ctx.font = '14px Arial';
            ctx.textAlign = 'center';
            ctx.fillText('Нет данных', size/2, size/2);
            return;
        }
        
        const moduleSize = size / 25;
        ctx.fillStyle = this._fgColor;
        
        const hash = this._hashString(data);
        for (let row = 0; row < 21; row++) {
            for (let col = 0; col < 21; col++) {
                const val = (hash * (row + 1) * (col + 1) + row * 7 + col * 13) % 5;
                if (val > 2) {
                    ctx.fillRect(col * moduleSize + moduleSize * 2, row * moduleSize + moduleSize * 2, moduleSize, moduleSize);
                }
            }
        }
        
        this._drawMarkers(ctx, moduleSize, size);
        ctx.fillStyle = '#666';
        ctx.font = '10px Arial';
        ctx.textAlign = 'center';
        ctx.fillText('Marka', size/2, size - 5);
    };

    QRCode.prototype._hashString = function(str) {
        let hash = 0;
        for (let i = 0; i < str.length; i++) {
            const char = str.charCodeAt(i);
            hash = ((hash << 5) - hash) + char;
            hash = hash & hash;
        }
        return Math.abs(hash) || 1;
    };

    QRCode.prototype._drawMarkers = function(ctx, moduleSize, size) {
        const markerSize = 7 * moduleSize;
        const positions = [[0, 0], [0, size - markerSize], [size - markerSize, 0]];
        ctx.fillStyle = this._fgColor;
        positions.forEach(([x, y]) => {
            ctx.fillRect(x, y, markerSize, markerSize);
            ctx.fillStyle = this._bgColor;
            ctx.fillRect(x + moduleSize, y + moduleSize, markerSize - moduleSize * 2, markerSize - moduleSize * 2);
            ctx.fillStyle = this._fgColor;
            ctx.fillRect(x + moduleSize * 2.5, y + moduleSize * 2.5, markerSize - moduleSize * 5, markerSize - moduleSize * 5);
            ctx.fillStyle = this._fgColor;
        });
    };

    global.QRCode = QRCode;
})(window);
